#include <iostream>
#include <string>

int main() {
    std::string input;
    std::getline(std::cin, input);

    int count4 = 0;
    int count7 = 0;

    if (input.find('4') != std::string::npos ||
        input.find('7') != std::string::npos) {
        for (char c : input) {
            if (c == '4') {
                ++count4;
            } else if (c == '7') {
                ++count7;
            }
        }

        if (count4 >= count7) {
            std::cout << 4 << '\n';
        } else {
            std::cout << 7 << '\n';
        }
    } else {
        std::cout << -1 << '\n';
    }

    return 0;
}

